<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Admin | Nomadic Traveler</title><style>body{font-family:Arial;background:#f3f6fb;margin:0;color:#14213d}.wrap{max-width:1000px;margin:5vh auto;padding:28px}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:16px}.card{background:white;border-radius:14px;padding:24px;box-shadow:0 8px 24px #13294b10}.num{font-size:2rem;font-weight:bold}</style></head><body><main class="wrap"><p><a href="{{ route('dashboard') }}">← Member dashboard</a></p><h1>Platform administration</h1><p>Restricted to the explicitly designated super administrator.</p><section class="cards"><div class="card">All accounts<div class="num">{{ $members }}</div></div><div class="card">Active accounts<div class="num">{{ $activeMembers }}</div></div><div class="card">Pending accounts<div class="num">{{ $pendingMembers }}</div></div></section></main></body></html>
